from pathlib import Path
import csv
import base64
import sys

CSV_DATEI = Path("reime.csv")
AUSGABE_DATEI = Path("index.html")
VERSION = "2.31"

# WICHTIG:
# Diese Schablone ist die aktuelle vollständige Reimfinder-Seite.
# Beim Aktualisieren der Reimwörter wird ausschließlich der Datenblock
# aus reime.csv ersetzt. Gestaltung, Google-Texte, Popup, Mobilansicht,
# "nach oben"-Funktion und der Abschnitt "Was dieser Reimfinder anders macht"
# bleiben dadurch erhalten.
HTML_TEMPLATE_B64 = ""


def lese_reime():
    if not CSV_DATEI.exists():
        print("Fehler: reime.csv wurde nicht gefunden.")
        sys.exit(1)

    gruppen = []
    with CSV_DATEI.open("r", encoding="utf-8-sig", newline="") as f:
        reader = csv.reader(f, delimiter=";")
        for zeilennummer, zeile in enumerate(reader, start=1):
            felder = [feld.strip() for feld in zeile if feld.strip()]
            if not felder:
                continue
            if len(felder) < 2:
                print(
                    f"Warnung: Zeile {zeilennummer} enthält keine "
                    "Reimwörter und wird ausgelassen."
                )
                continue
            gruppen.append(felder)

    if not gruppen:
        print("Fehler: In reime.csv wurden keine gültigen Reimgruppen gefunden.")
        sys.exit(1)

    return gruppen


def sichere_javascript_daten(text):
    return (
        text.replace("\\", "\\\\")
            .replace("`", "\\`")
            .replace("${", "\\${")
    )


def main():
    gruppen = lese_reime()

    daten = "\n".join(";".join(gruppe) for gruppe in gruppen)
    daten = sichere_javascript_daten(daten)

    template = base64.b64decode(HTML_TEMPLATE_B64).decode("utf-8")

    if "__REIMDATEN__" not in template:
        print("Fehler: Datenplatzhalter fehlt in der HTML-Schablone.")
        sys.exit(1)

    html = template.replace("__REIMDATEN__", daten, 1)
    AUSGABE_DATEI.write_text(html, encoding="utf-8")

    anzahl_woerter = sum(len(gruppe) - 1 for gruppe in gruppen)

    print("Fertig!")
    print("Erstellt:", AUSGABE_DATEI.name)
    print("Builder-Version:", VERSION)
    print("Reimgruppen:", len(gruppen))
    print("Reimwörter:", anzahl_woerter)
    print("Die aktuelle Seitengestaltung wurde beibehalten.")


if __name__ == "__main__":
    main()
